def format_path_with_project_root_or_depth(path: str, depth: int = 1) -> str:
    """
    Formats the path to include the project root or a specified depth in the file system.
    """
    project_root = os.path.abspath(os.path.join(os.getcwd(), os.pardir))
    formatted_path = os.path.join(project_root, path)
    if depth > 1:
        formatted_path = os.path.join(formatted_path, os.pardir) * (depth - 1)
    return os.path.abspath(formatted_path)

